-- Moneta-Mira supplies catalog identity evidence from its old and modern coin archive. Prices are excluded.
UPDATE catalog_source SET adapter_key='moneta-mira-html',status='probing',price_role='none',access_review_status='allowed',access_reviewed_at=now(),poll_interval=interval '7 days',next_poll_at=now(),last_error=NULL,
notes=concat_ws(E'\n',NULLIF(notes,''),'Robots.txt permits public product paths and declares sitemapyandex.xml. Discovery keeps all URLs below the foreign, USSR and Russian coin roots. A real product id, structured identity fields, one unambiguous title year and a source image showing both coin sides are required. Old and unavailable cards remain eligible. Product prices and offers are ignored and never stored.'),updated_at=now() WHERE source_key='moneta-mira.ru';
